def _transpose_pitch_carrier_by_melodic_chromatic_interval(pitch_carrier, melodic_chromatic_interval):
    from abjad.tools import chordtools
    from abjad.tools import componenttools
    from abjad.tools import notetools
    from abjad.tools import pitchtools
    mci = pitchtools.MelodicChromaticInterval(melodic_chromatic_interval)
    if isinstance(pitch_carrier, pitchtools.Pitch):
        return type(pitch_carrier)(pitch_carrier.chromatic_pitch_number + mci.semitones)
    elif isinstance(pitch_carrier, numbers.Number):
        pitch_carrier = pitchtools.NumberedChromaticPitch(pitch_carrier)
        result = _transpose_pitch_carrier_by_melodic_chromatic_interval(pitch_carrier, mci)
        return result.chromatic_pitch_number
    elif isinstance(pitch_carrier, notetools.Note):
        new_note = componenttools.copy_components_and_remove_spanners([pitch_carrier])[0]
        new_pitch = pitchtools.NamedChromaticPitch(abs(pitch_carrier.written_pitch.numbered_chromatic_pitch) + mci.number)
        new_note.written_pitch = new_pitch
        return new_note
    elif isinstance(pitch_carrier, chordtools.Chord):
        new_chord = componenttools.copy_components_and_remove_spanners([pitch_carrier])[0]
        for (new_nh, old_nh) in zip(new_chord.note_heads, pitch_carrier.note_heads):
            new_pitch = pitchtools.NamedChromaticPitch(abs(old_nh.written_pitch.numbered_chromatic_pitch) + mci.number)
            new_nh.written_pitch = new_pitch
        return new_chord
    else:
        return pitch_carrier

def rm_correlated(self, df, target_key, R_max=0.95):
    corr = abs(df.corr())
    if target_key in corr:
        corr = corr.sort_values(by=target_key)
    rm_feats = []
    for feature in corr.columns:
        if feature == target_key:
            continue
        for (idx, corval) in zip(corr.index, corr[feature]):
            if np.isnan(corval):
                break
            if idx == feature or idx in rm_feats:
                continue
            elif corval >= R_max:
                if corr.loc[idx, target_key] > corr.loc[feature, target_key]:
                    removed_feat = feature
                else:
                    removed_feat = idx
                if removed_feat not in rm_feats:
                    rm_feats.append(removed_feat)
                    self.logger.debug('"{}" correlates strongly with "{}"'.format(feature, idx))
                    self.logger.debug('removing "{}"...'.format(removed_feat))
                if removed_feat == feature:
                    break
    if len(rm_feats) > 0:
        df = df.drop(rm_feats, axis=1)
        self.logger.info('These {} features were removed due to cross correlation with the current features more than {}:\n{}'.format(len(rm_feats), R_max, rm_feats))
    return df

def rm_correlated(self, df, target_key, R_max=0.95):
