def create_trade_source(sids, trade_count, trade_time_increment, sim_params, concurrent=False):
    args = tuple()
    kwargs = {'count': trade_count, 'sids': sids, 'start': sim_params.first_open, 'delta': trade_time_increment, 'filter': sids, 'concurrent': concurrent}
    source = SpecificEquityTrades(*args, **kwargs)
    sim_params.period_end = sim_params.first_open + (trade_count - 1) * trade_time_increment
    return source

