    if client_required and _client == '':
        raise UsageError('set a client name with musicbrainz.set_client("client-version")')
    elif client_required:
        args['client'] = _client
    url = urlparse.urlunparse(('http', hostname, '/ws/2/%s' % path, '', urllib.urlencode(args), ''))
    f = _make_http_request(url, auth_required, data, body, method)
    return mbxml.parse_message(f)

