def _object_as_string(self, object):
    registry = self._registry
    if object in registry:
        sid = registry.get(object).script_id
        self.write_script_id_in_namespace(sid)
        return sid
    else:
        ob_id = id(object)
        orepr = repr(object)
        if hex(ob_id) not in orepr:
            return orepr
    return repr(object)

def getActualSize(self, partitions, diskset):
    size = 0
    for drive in self.drive:
        part = diskset.disks[drive].getPartitionByPath('/dev/%s' % self.device)
        if not part:
            return 0
        size += part.getSize(unit='MB')
    return size

def findInitialVertex(self, allVertices):
    i = len(allVertices) - 1
    while i >= 0:
        j = self.indexInRange(i)
        if (j not in self.notchVertices and j + len(allVertices) not in self.notchVertices and (j - len(allVertices) not in self.notchVertices)) and (not self.calcAngle(allVertices[j - 1], allVertices[j], allVertices[j + 1])):
            self.indexOfVertex = self.indexInRange(j + 1)
            self.vertexIndexOfNextPoly.append(j)
            self.vertexIndexOfNextPoly.append(self.indexOfVertex)
            break
        else:
            i = i - 1

