def load(Loader, representation, namespace=None, name=None, data=None):
    Loader = _make_backwards_compatible_loader(Loader)
    context = _get_representation_context(representation)
    if data is None:
        data = dict()
    assert isinstance(data, dict), 'Data must be a dictionary'
    if name is None:
        name = context['subset']['name']
    assert hasattr(Loader, 'load'), "Loader must have a 'load' method"
    log.info("Running '%s' on '%s" % (Loader.__name__, context['asset']['name']))
    loader = Loader(context)
    return loader.load(context=context, name=name, namespace=namespace, data=data)

def __mode_from_size_segment(size_segment):
    if size_segment.split(':')[0] == 'pct':
        return PCT_MODE
    elif size_segment == 'full':
        return FULL_MODE
    elif not ',' in size_segment:
        msg = 'Size syntax "%s" is not valid' % (size_segment,)
        raise SyntaxException(http_status=400, message=msg)
    elif all([n.isdigit() or n == '' for n in size_segment.split(',')]):
        return PIXEL_MODE
    elif all([n.isdigit() for n in size_segment[1:].split(',')]) and len(size_segment.split(',')) == 2:
        return PIXEL_MODE
    else:
        msg = 'Size syntax "%s" is not valid' % (size_segment,)
        raise SyntaxException(http_status=400, message=msg)

def __mode_from_size_segment(size_segment):
    if size_segment.startswith('pct:'):
