def _check_X_y(X, y, dtype='numeric', accept_sparse=False, order=None, copy=False, force_all_finite=True, ensure_2d=True, y_numeric=False):
    if y is None:
        raise ValueError('y cannot be None')
    X = _check_array(X, accept_sparse=accept_sparse, dtype=dtype, order=order, copy=copy, force_all_finite=force_all_finite, ensure_2d=ensure_2d)
    y = _column_or_1d(y, warn=True)
    if y_numeric and y.dtype.kind == 'O':
        y = y.astype(np.float64)
    from daal4py import assert_all_finite
    assert_all_finite(y)
    lengths = [len(X), len(y)]
    uniques = np.unique(lengths)
    if len(uniques) > 1:
        raise ValueError('Found input variables with inconsistent numbers of samples: %r' % [int(length) for length in lengths])
    return (X, y)

def get_xray_structures(processed_pdb_file, scattering_table, d_min):
    xray_structure = processed_pdb_file.xray_structure()
    if xray_structure is None or xray_structure.scatterers().size() == 0:
        raise Sorry('Cannot extract xray_structure.')
    if scattering_table != 'neutron':
        xray_structure.scattering_type_registry(table=scattering_table, d_min=d_min, types_without_a_scattering_contribution=['?'])
    else:
        xray_structure.scattering_type_registry(types_without_a_scattering_contribution=['?'])
        xray_structure.switch_to_neutron_scattering_dictionary()
    model_indices = processed_pdb_file.all_chain_proxies.pdb_inp.model_indices()
    if len(model_indices) > 1:
        result = []
        model_indices_padded = flex.size_t([0])
        model_indices_padded.extend(model_indices)
        ranges = []
        for (i, v) in enumerate(model_indices_padded):
            try:
                ranges.append([model_indices_padded[i], model_indices_padded[i + 1]])
            except IndexError:
                pass
        for ran in ranges:
            sel = flex.size_t(range(ran[0], ran[1]))
            result.append(xray_structure.select(sel))
        return result
    else:
        return [xray_structure]

def _get_fragment(self, chunk_iter, storage_method):
    reader = io.ChunkReader(chunk_iter, storage_method.ec_fragment_size, storage_method.request_headers, self.connection_timeout, self.response_timeout, self.read_timeout)
