def displayCategories(self, builderList, debugInfo):
    count = 0
    for category in builderList:
        count += len(builderList[category])
    categories = list(builderList.keys())
    categories.sort()
    cs = []
    for category in categories:
        c = {}
        c['name'] = category.lstrip('0123456789')
        c['size'] = len(builderList[category]) * 100 / count
        cs.append(c)
    return cs

def _metadata_column_factory(self, series):
    dtype = series.dtype
    if NumericMetadataColumn._is_supported_dtype(dtype):
        column = NumericMetadataColumn(series)
    elif CategoricalMetadataColumn._is_supported_dtype(dtype):
        column = CategoricalMetadataColumn(series)
    else:
        raise TypeError('Metadata column %r has an unsupported pandas dtype %r' % (series.name, dtype))
    column._add_artifacts(self.artifacts)
    return column

def _metadata_column_factory(self, series):
    dtype = series.dtype
    if NumericMetadataColumn._is_supported_dtype(dtype):
        column = NumericMetadataColumn(series)
    elif CategoricalMetadataColumn._is_supported_dtype(dtype):
        column = CategoricalMetadataColumn(series)
    elif dtype == 'bool':
        raise TypeError('Metadata column %r has an unsupported pandas dtype %r' % (series.name, dtype))
    else:
        raise TypeError('Metadata column %r has an unsupported pandas dtype %r' % (series.name, dtype))
    column._add_artifacts(self.artifacts)
    return column

def _get_server_certificate_provider(self, instance_id: str) -> CertificateProvider:
    if self._is_provider_a(instance_id):
        return ProviderA()
    elif self._is_provider_b(instance_id):
        return ProviderB()
    return NullCertificateProvider()

def main():
    args = parse_args()
    assert args.out or args.eval or args.format_only or args.show\
        or args.show_dir,\
        ('Please specify at least one operation (save/eval/format/show the '
         'results / save the results) with the argument "--out", "--eval"'
         ', "--format-only", "--show" or "--show-dir")
    if args.eval and args.format_only:
        raise ValueError('--eval and --format_only cannot be both specified')
    if args.out is not None and not args.out.endswith(('.pkl', '.pickle')):
        raise ValueError('The output file must be a pkl file.')
    cfg = Config.fromfile(args.config)
    if args.cfg_options is not None:
        cfg.merge_from_dict(args.cfg_options)
    if cfg.get('cudnn_benchmark', False):
        torch.backends.cudnn.benchmark = True
    cfg.model.pretrained = None
    necks = cfg.model.get('neck')
    if necks:
        necks = necks if isinstance(necks, list) else [necks]
        for neck in necks:
            if neck.get('rfp_backbone'):
                if neck.rfp_backbone.get('pretrained'):
                    neck.rfp_backbone.pretrained = None
    cfg.data.test.test_mode = True
    if args.launcher == 'none':
        distributed = False
    else:
        distributed = True
        init_dist(args.launcher, **cfg.dist_params)
    dataset = build_dataset(cfg.data.test)
    data_loader = build_dataloader(
        dataset,
        samples_per_gpu=2,
        workers_per_gpu=cfg.data.workers_per_gpu,
        dist=distributed,
        shuffle=False)
    model = build_detector(cfg.model, train_cfg=None, test_cfg=cfg.test_cfg)
    fp16_cfg = cfg.get('fp16', None)
    if fp16_cfg is not None:
        wrap_fp16_model(model)
    checkpoint = load_checkpoint(model, args.checkpoint, map_location='cpu')
    classes_rearrange = cfg.get('classes_rearrange', False)
    if classes_rearrange:
        model = rearrange_classes(model, cfg.classes, cfg.dataset_type)
    if args.fuse_conv_bn:
        model = fuse_module(model)
    if 'CLASSES' in checkpoint['meta']:
        model.CLASSES = checkpoint['meta']['CLASSES']
    else:
        model.CLASSES = dataset.CLASSES
    if not distributed:
        model = MMDataParallel(model, device_ids=[0])
        outputs = single_gpu_test(model, data_loader, args.show, args.show_dir,
                                  args.show_score_thr)
    else:
        model = MMDistributedDataParallel(
            model.cuda(),
            device_ids=[torch.cuda.current_device()],
            broadcast_buffers=False)
        outputs = multi_gpu_test(model, data_loader, args.tmpdir,
                                 args.gpu_collect)
    rank, _ = get_dist_info()
    if rank == 0:
        if args.out:
            print(f'\nwriting results to {args.out}')
            mmcv.dump(outputs, args.out)
        kwargs = {} if args.options is None else args.options
        if args.format_only:
            dataset.format_results(outputs, **kwargs)
        if args.eval:
            dataset.evaluate(outputs, args.eval, **kwargs)

