def build_uniform_param_grid(ansatz_specs: Dict, number_of_params_per_layer: Union[str, int]=None, number_of_layers: int=1, min_value: float=0, max_value: float=2 * np.pi, step: float=np.pi / 5):
    if ansatz_specs is not None:
        ansatz = create_object(json.loads(ansatz_specs))
        number_of_params = ansatz.number_of_params
    elif number_of_params_per_layer is not None:
        number_of_params = number_of_params_per_layer
    grid = _build_uniform_param_grid(number_of_params, number_of_layers, min_value, max_value, step)
    save_parameter_grid(grid, 'parameter-grid.json')

def testPasswordProtectedSite(self):
    test_support.requires('network')
    url = 'http://mueblesmoraleda.com'
    parser = robotparser.RobotFileParser()
    parser.set_url(url)
    try:
        parser.read()
    except IOError:
        self.skipTest('%s is unavailable' % url)
    self.assertEqual(parser.can_fetch('*', url + '/robots.txt'), False)

def testPasswordProtectedSite(self):
    test_support.requires('network')
    url = 'http://mueblesmoraleda.com'
    parser = robotparser.RobotFileParser()
    parser.set_url(url)
    try:
        parser.read()
    except IOError:
        self.skipTest('%s is unavailable' % url)
    self.assertEqual(parser.can_fetch('*', url + '/robots.txt'), False)

