def can_be_main_file(directory_entry: typing.Any, project: typing.Any) -> bool:
    if not isinstance(directory_entry, DirectoryListEntry):
        return False
    directory_entry = typing.cast(DirectoryListEntry, directory_entry)
    if not isinstance(project, Project):
        return False
    project = typing.cast(Project, project)
    if directory_entry.is_directory:
        return False
    return not is_main_file(directory_entry, project)

async def from_id(cls, client: Client, channel_id: int) -> Channel:
    data = await client.http.get(f'channels/{channel_id}') or {}
    data.update(construct_client_dict(client, {'type': ChannelType(data.pop('type'))}))
    channel_cls = _channel_type_map.get(data['type'], Channel)
    return channel_cls.from_dict(data)

def on_validation_batch_end(self, trainer, pl_module, outputs, batch, batch_idx, dataloader_idx):
    if trainer.sanity_checking:
        self._update(self.val_sanity_progress_bar_id, self.val_batch_idx, self.total_val_batches_current_dataloader)
    elif self.val_progress_bar_id is not None:
        if self.main_progress_bar_id is not None:
            self._update(self.main_progress_bar_id, self.val_batch_idx, self.val_processed)
        self._update(self.val_progress_bar_id, self.val_batch_idx, self.total_val_batches_current_dataloader)
    self.refresh()

def symmetric_poly(n, *gens, polys=False):
    gens = _analyze_gens(gens)
    if n < 0 or n > len(gens) or (not gens):
        raise ValueError('Cannot generate symmetric polynomial of order %s for %s' % (n, gens))
    elif not n:
        poly = S.One
    else:
        poly = Add(*[Mul(*s) for s in subsets(gens, int(n))])
    if not polys:
        return poly
    else:
        return Poly(poly, *gens)

