def buildImportFromNode(provider, node, source_ref):
    module_name = node.module if node.module is not None else ''
    level = node.level
    if module_name == '__future__':
        if not provider.isCompiledPythonModule():
            SyntaxErrors.raiseSyntaxError(reason='\nfrom __future__ imports must occur at the beginning of the file', col_offset=8 if python_version >= 300 or not Options.isFullCompat() else None, source_ref=source_ref)
        for import_desc in node.names:
            (object_name, _local_name) = (import_desc.name, import_desc.asname)
            enableFutureFeature(object_name=object_name, future_spec=source_ref.getFutureSpec(), source_ref=source_ref)
        node.source_ref = source_ref
        _future_import_nodes.append(node)
    target_names = []
    import_names = []
    for import_desc in node.names:
        (object_name, local_name) = (import_desc.name, import_desc.asname)
        if object_name == '*':
            target_names.append(None)
        else:
            target_names.append(local_name if local_name is not None else object_name)
        import_names.append(object_name)
    if None in target_names:
        assert target_names == [None]
        if not provider.isCompiledPythonModule() and python_version >= 300:
            SyntaxErrors.raiseSyntaxError('import * only allowed at module level', provider.getSourceReference())
        if provider.isExpressionFunctionBody():
            provider.markAsStarImportContaining()
        return StatementImportStar(module_import=ExpressionImportModule(module_name=module_name, import_list=('*',), level=level, source_ref=source_ref), source_ref=source_ref)
    else:

        def makeImportName(import_name):
            if module_name == '__future__':
                return ExpressionImportModuleHard(module_name='__future__', import_name=import_name, source_ref=source_ref)
            else:
                import_module = ExpressionImportModule(module_name=module_name, import_list=tuple(import_names), level=level, source_ref=source_ref)
                return ExpressionImportName(module=import_module, import_name=import_name, source_ref=source_ref)
        import_nodes = []
        for (target_name, import_name) in zip(target_names, import_names):
            import_nodes.append(StatementAssignmentVariable(variable_ref=ExpressionTargetVariableRef(variable_name=mangleName(target_name, provider), source_ref=source_ref), source=makeImportName(import_name=import_name), source_ref=source_ref))
        return StatementsSequence(statements=import_nodes, source_ref=source_ref)

def find_common_filenames(list1, list2):
    lf = [Path(d['file']).stem for d in list1]
    rf = [Path(d['file']).stem for d in list2]
    if 'image' in rf[0][0:5]:
        if len(lf[0]) == 32:
            lf = [Path(d['file']).stem[13:28] for d in list1]
            rf = [Path(d['file']).stem[13:28] for d in list2]
        else:
            lf = [Path(d['file']).stem[5:] for d in list1]
            rf = [Path(d['file']).stem[5:] for d in list2]
    result = []
    for (i, lname) in enumerate(lf):
        for (j, rname) in enumerate(rf):
            if lname == rname:
                result.append((list1[i], list2[j]))
    return result

