def isAddressInSections(self, address, length=0, sectiontype=''):
    if not self.internalblue.fw.SECTIONS:
        return False
    for section in self.internalblue.fw.SECTIONS:
        if sectiontype.upper() == 'ROM' and (not section.is_rom) or (sectiontype.upper() == 'RAM' and (not section.is_ram)):
            continue
        if address >= section.start_addr and address <= section.end_addr:
            if address + length <= section.end_addr:
                return True
            else:
                return False
    return False

def _patchLog(self, log, count):
    log.setHeader(self.logHeader)
    log(self.logWeightValue % self.weight)
    log(self.logMsg % sum(count.values()))
    for srcMod in bosh.modInfos.getOrdered(count.keys()):
        log(u'  * %s: %d' % (srcMod.s, count[srcMod]))

def _generate_bridge_operation(self, version=1):
    addrs = self._generate_addresses(version=version)
    bridge_operation = self._get_initial_params()
    if version == 1:
        bridge_operation.update({'id': self.name, 'type': 'bridge', 'name': self.name, 'mac_address': str(self.iface.mac_address), 'bridge_interfaces': [parent.get_name() for parent in self.iface.parents.order_by('name')], 'params': self._get_bridge_params()})
        if addrs:
            bridge_operation['subnets'] = addrs
    elif version == 2:
        bridge_operation.update({'interfaces': [parent.get_name() for parent in self.iface.parents.order_by('name')]})
        bridge_params = get_netplan_bridge_parameters(self._get_bridge_params())
        if len(bridge_params) > 0:
            bridge_operation['parameters'] = bridge_params
        bridge_operation.update(addrs)
    return bridge_operation

