def post(resource):
    if len(request.form) == 0:
        abort(400)
    response = dict()
    date_utc = datetime.utcnow()
    schema = app.config['DOMAIN'][resource]['schema']
    validator = app.validator(schema, resource)
    for (key, value) in request.form.items():
        response_item = dict()
        issues = list()
        try:
            document = parse(value, resource)
            validation = validator.validate(document)
            if validation:
                document[LAST_UPDATED] = document[DATE_CREATED] = date_utc
                document[ID_FIELD] = app.data.insert(resource, document)
                document[ID_FIELD] = key
                response_item[ID_FIELD] = document[ID_FIELD]
                response_item[LAST_UPDATED] = document[LAST_UPDATED]
                response_item['link'] = document_link(resource, response_item[ID_FIELD])
            else:
                issues.append(validator.errors)
        except ValidationError as e:
            raise e
        except Exception as e:
            issues.append(str(e))
        if len(issues):
            response_item['issues'] = issues
            response_item['status'] = STATUS_ERR
        else:
            response_item['status'] = STATUS_OK
        response[key] = response_item
    return (response, None, None, 200)

def _EmptyStrOrError(self, val, token=None):
    assert isinstance(val, runtime.value), val
    if val.tag == value_e.Undef:
        if self.exec_opts.nounset:
            token = None
            log(f'UNDEFINED: {token} (todo: show error)')
            raise _EvalError('Undefined variable', token=token)
        else:
            return runtime.Str('')
    else:
        return val

def get_det_bboxes(self, rois, cls_score, bbox_pred, img_shape, scale_factor, rescale=False, cfg=None):
    if isinstance(cls_score, list):
        cls_score = sum(cls_score) / float(len(cls_score))
    scores = F.softmax(cls_score, dim=1) if cls_score is not None else None
    if bbox_pred is not None:
        bboxes = delta2bbox(rois[:, 1:], bbox_pred, self.target_means, self.target_stds, img_shape)
    else:
        bboxes = rois[:, 1:]
        bboxes = bboxes.clamp(min=0, max=img_shape[1] - 1)
    if rescale:
        bboxes /= scale_factor
    if cfg is None:
        return (bboxes, scores)
    else:
        (det_bboxes, det_labels) = multiclass_nms(bboxes, scores, cfg.score_thr, cfg.nms, cfg.max_per_img)
        return (det_bboxes, det_labels)

