def pixel_coords_to_space_coords(self, px, py, relative=False):
    (pw, ph) = self.get_pixel_shape()
    (fw, fh) = self.get_frame_shape()
    fc = self.get_frame_center()
    if relative:
        return 2 * np.array([px / pw, py / ph, 0])
    else:
        scale = fh / ph
        return fc + scale * np.array([px - pw / 2, py - ph / 2, 0])

def _yield_all_checks(name, Estimator):
    sklearn_yield_all_checks(name, Estimator)
    if issubclass(Estimator, SamplerMixin):
        for check in _yield_sampler_checks(name, Estimator):
            yield check

def createfourierdesignmatrix_dm(toas, freqs, nmodes=30, Tspan=None, pshift=False, logf=False, fmin=None, fmax=None, modes=None):
    (F, Ffreqs) = createfourierdesignmatrix_red(toas, nmodes=nmodes, Tspan=Tspan, logf=logf, fmin=fmin, fmax=fmax, pshift=pshift, modes=modes)
    Dm = 1.0 / (const.DM_K * freqs ** 2 * 1000000000000.0)
    return (F * Dm[:, None], Ffreqs)

def forward(self, previous_state: Dict[str, torch.Tensor], encoder_outputs: torch.Tensor, source_mask: torch.BoolTensor, previous_steps_predictions: torch.Tensor, previous_steps_mask: Optional[torch.BoolTensor]=None) -> Tuple[Dict[str, torch.Tensor], torch.Tensor]:
    decoder_hidden = previous_state['decoder_hidden']
    decoder_context = previous_state['decoder_context']
    last_predictions_embedding = previous_steps_predictions[:, -1]
    if self._attention:
        attended_input = self._prepare_attended_input(decoder_hidden, encoder_outputs, source_mask)
        decoder_input = torch.cat((attended_input, last_predictions_embedding), -1)
    else:
        decoder_input = last_predictions_embedding
    with torch.cuda.amp.autocast():
        (decoder_hidden, decoder_context) = self._decoder_cell(decoder_input.float(), (decoder_hidden.float(), decoder_context.float()))
    return ({'decoder_hidden': decoder_hidden, 'decoder_context': decoder_context}, decoder_hidden)

def gui_loop(slp=0):
    start = time.time()
    app = wx.GetApp()
    if app is None:
        return
    while time.time() < start + slp:
        wx.CallAfter(app.ExitMainLoop)
        app.MainLoop()

def _read_csv_file(file_name, verbose=False):
    file_pointer = open(file_name)
    (header, file_pointer) = _read_csv_file_header(file_pointer)
    while True:
        try:
            (pointlist, att_dict, file_pointer) = _read_csv_file_blocking(file_pointer, header, max_read_lines=float('inf'))
        except StopIteration:
            break
    file_pointer.close()
    return (pointlist, att_dict, None)

def annotate_interactions(bases, amino_acids, aa_part, dist_cent_cutoff, baseCubeList, baseCubeNeighbors, aaCubeList):
    count_pair = 0
    list_aa_coord = []
    list_base_coord = []
    aaList_len = None
    new_aaList_len = None
    list_base_aa = []
    for key in baseCubeList:
        for aakey in baseCubeNeighbors[key]:
            if aakey in aaCubeList:
                for base_residue in baseCubeList[key]:
                    base_seq = base_residue.sequence
                    base_atoms = NAbaseheavyatoms[base_seq]
                    base_center = base_residue.centers['base']
                    if not base_center.any():
                        continue
                    if not base_residue.centers[planar_atoms[base_seq][0]].any():
                        continue
                    if not base_residue.centers[planar_atoms[base_seq][1]].any():
                        continue
                    if not base_residue.centers[planar_atoms[base_seq][2]].any():
                        continue
                    for aa_residue in aaCubeList[aakey]:
                        aa_center = aa_residue.centers[aa_part]
                        if not aa_center.any():
                            continue
                        if aa_residue.sequence in set(['LYS', 'SER', 'THR', 'TYR']):
                            atom_distance_count = 1
                        else:
                            atom_distance_count = 2
                        if abs(base_center[0] - aa_center[0]) < dist_cent_cutoff and abs(base_center[1] - aa_center[1]) < dist_cent_cutoff and (np.linalg.norm(np.subtract(base_center, aa_center)) < dist_cent_cutoff) and atom_dist_basepart(base_residue, aa_residue, base_atoms, atom_distance_count):
                            count_pair = count_pair + 1
                            rotation_matrix = base_residue.rotation_matrix
                            base_coordinates = {}
                            standard_base = base_residue.translate_rotate_component(base_residue)
                            for base_atom in standard_base.atoms():
                                base_coordinates[base_atom.name] = base_atom.coordinates()
                            aa_coordinates = {}
                            standard_aa = base_residue.translate_rotate_component(aa_residue)
                            for aa_atom in standard_aa.atoms():
                                aa_coordinates[aa_atom.name] = aa_atom.coordinates()
                            standard_aa_center = standard_aa.centers[aa_part]
                            interaction = type_of_interaction(base_residue, aa_residue, aa_coordinates)
                            base_aa = None
                            if interaction == 'pseudopair' and enough_HBs(base_residue, aa_residue, base_atoms):
                                (edge, angle) = detect_edge(base_residue, base_coordinates, aa_residue, aa_coordinates)
                                base_aa = (base_residue, aa_residue, interaction, edge, standard_aa_center, angle)
                            elif interaction == 'SHB':
                                (edge, angle) = detect_edge(base_residue, base_coordinates, aa_residue, aa_coordinates)
                                base_aa = (base_residue, aa_residue, interaction, edge, standard_aa_center, angle)
                            elif interaction == 'perpendicular-edge':
                                (edge, angle) = detect_edge(base_residue, base_coordinates, aa_residue, aa_coordinates)
                                base_aa = (base_residue, aa_residue, interaction, edge, standard_aa_center, angle)
                            elif interaction == 'stacked' or interaction == 'cation-pi' or interaction == 'perpendicular-stacking':
                                (face, height) = detect_face(aa_residue, aa_coordinates)
                                base_aa = (base_residue, aa_residue, interaction, face, standard_aa_center, height)
                            if base_aa is not None:
                                list_base_aa.append(base_aa)
                                for base_atom in base_residue.atoms():
                                    list_base_coord.append(base_coordinates)
                                for aa_atom in aa_residue.atoms():
                                    list_aa_coord.append(aa_coordinates)
    return (list_base_aa, list_aa_coord, list_base_coord)

def testValueError(self) -> None:
    with self.assertRaises(ValueError):
        Winsorize(search_space=None, observations=deepcopy(self.observations), config={'winsorization_lower': 0.8, 'percentile_bounds': {'m1': (0.1, 0.2, 0.3)}})

def _try_delete_uri(mlmd_handle: metadata.Metadata, uri: str) -> None:
    artifacts = mlmd_handle.store.get_artifacts_by_uri(uri)
    if any([a.state != metadata_store_pb2.Artifact.State.MARKED_FOR_DELETION for a in artifacts]):
        return
    logging.info('Deleting URI %s', uri)
    if os.path.isfile(uri):
        logging.warning('Cannot delete a file directly: %s', uri)
        return
    io_utils.delete_dir(uri)
    _update_artifacts_state(mlmd_handle, artifacts, metadata_store_pb2.Artifact.State.DELETED)

def _standardize_curie_or_iri(curie_or_iri: str, *, converter: Converter) -> str:
    if converter.is_uri(curie_or_iri):
        return converter.compress_uri(curie_or_iri)
    if converter.is_curie(curie_or_iri):
        return converter.standardize_curie(curie_or_iri, strict=True)
    return curie_or_iri

def imul(info, a, b=None, c=None):
    e = []
    if b == None:
        if a.get_size() == 32:
            c_hi = ExprOp('imul32_hi', eax, a)
            c_lo = ExprOp('imul32_lo', eax, a)
            e.append(ExprAff(edx, c_hi))
            e.append(ExprAff(eax, c_lo))
        elif a.get_size() == 16:
            c_hi = ExprOp('imul16_hi', r_ax, a)
            c_lo = ExprOp('imul16_lo', r_ax, a)
            e.append(ExprAff(r_dx, c_hi))
            e.append(ExprAff(r_ax, c_lo))
        elif a.get_size() == 8:
            c = ExprOp('imul08', eax, a)
            e.append(ExprAff(eax[:16], c))
    else:
        if c == None:
            c = b
            b = a
        c = ExprOp('*', b, c)
        e.append(ExprAff(a, c))
    return e

