async def _send_request_to_api(self, method, path, raise_on_failure: bool=False, **kwargs):
    url = f'{self._api_url}/api/{mlrun.mlconf.api_base_version}/{path}'
    if kwargs.get('timeout') is None:
        kwargs['timeout'] = mlrun.mlconf.httpdb.clusterization.worker.request_timeout or 20
    logger.debug('Sending request to chief', method=method, url=url, **kwargs)
    response = await self._session.request(method, url, verify=False, **kwargs)
    if not response.ok:
        log_kwargs = copy.deepcopy(kwargs)
        log_kwargs.update({'method': method, 'path': path})
        if response.content:
            try:
                data = await response.json()
                error = data.get('error')
                error_stack_trace = data.get('errorStackTrace')
            except Exception:
                pass
            else:
                log_kwargs.update({'error': error, 'error_stack_trace': error_stack_trace})
        logger.warning('Request to chief failed', **log_kwargs)
        if raise_on_failure:
            mlrun.errors.raise_for_status(response)
        return response
    try:
        data = await response.json()
    except Exception:
        data = response.text
    logger.debug('Request to chief succeeded', method=method, url=url, **kwargs, response=data)
    return response

def add(self, conn: Conn, packet: server_packets.PublicChannelJoined):
    if not conn.is_main:
        return
    conn.channels[packet.channel_id] = packet
    if not conn.org_id and self.is_org_channel_id(packet.channel_id):
        conn.org_channel_id = packet.channel_id
        conn.org_id = 4294967295 & packet.channel_id
        if packet.name != 'Clan (name unknown)':
            self.setting_service.get('org_name').set_value(packet.name)
            conn.org_name = packet.name
        self.logger.info(f"Org info for '{conn.id}': {conn.org_name} ({conn.org_id})")

def base_test_protocol(folder_name: str, protocol: SourceProto | DestinationProto):
    modules = dag_utils.import_modules_from_folder(folder_name)
    for module in modules:
        target_class = 'Source' if protocol.__name__ == 'SourceProto' else 'Destination' if protocol.__name__ == 'DestinationProto' else None
        if not target_class:
            raise ValueError(f'Provided protocol {protocol} not supported.')
        implementation = getattr(module, target_class)
        assert issubclass(implementation, protocol)
        target_methods = inspect.getmembers(implementation, inspect.isfunction)
        protocol_methods = inspect.getmembers(protocol, inspect.isfunction)
        for (required_name, required_method) in protocol_methods:
            for (target_name, target_method) in target_methods:
                if required_name == target_name and target_name != '__init__':
                    assert inspect.signature(required_method) == inspect.signature(target_method)
                elif target_name == '__init__':
                    pass

