                if required_name == target_name and target_name != '__init__':
                    assert inspect.signature(required_method) == inspect.signature(target_method)
                elif required_name == '__init__' and target_name == '__init__':
                    pass

def __call__(self, entries):
    accounts = set()
    for entry in entries:
        method = getattr(self, entry.__class__.__name__)
        for account in method(entry):
            accounts.add(account)
    return accounts

def __init__(self, limits):
    self._limits = limits
    logging.debug('Created SubsetConstraint of type %s', self.__class__.__name__)

def __getitem__(self, key):
    if key in self._pb_body.keys():
        value = self._pb_body[key]
        if isinstance(value, struct_pb2.Struct):
            return StructView(value)
        elif isinstance(value, struct_pb2.ListValue):
            return ListValueView(value)
        else:
            return value
    else:
        raise KeyError()

def _set_root(self, root_identifier):
    assert isinstance(root_identifier, (str, type(None)))
    if isinstance(self.anchor, (str, type(None))):
        self._anchor = root_identifier
    else:
        anchor = copy.deepcopy(self.anchor)
        anchor._set_root(root_identifier)
        self._anchor = anchor

def get_fallthrough_recipients(project: Project, fallthrough_choice: FallthroughChoiceType) -> Iterable[APIUser]:
    if not features.has('organizations:issue-alert-fallback-targeting', project.organization, actor=None):
        return []
    if fallthrough_choice == FallthroughChoiceType.NO_ONE:
        return []
    elif fallthrough_choice == FallthroughChoiceType.ALL_MEMBERS:
        return user_service.get_from_project(project.id)
    elif fallthrough_choice == FallthroughChoiceType.ADMIN_OR_RECENT:
        return user_service.get_from_project(project.id)
    return []

def depths(self):
    depths = {}
    queue = [(self.root, 0)]
    while queue:
        (node, depth) = queue.pop(0)
        depths[node.clade] = depth
        for child in node.children:
            queue.append((child, depth + child.branch_length))
    return depths

def depths(self):
    depths = {}
    queue = [(self.root, 0)]
    while queue:
        (current, depth) = queue.pop(0)
        depths[current] = depth
        for child in current.children:
            queue.append((child, depth + child.branch_length))
    return depths

def run(self, num_l_gripper_pushes, num_l_sweeps, num_l_overhead_pushes, num_r_gripper_pushes, num_r_sweeps, num_r_overhead_pushes):
    rospy.loginfo('Getting table pose')
    table_req = LocateTableRequest()
    table_req.recalculate = True
    raise_req = RaiseAndLookRequest()
    try:
        table_res = self.table_proxy(table_req)
    except rospy.ServiceException as e:
        rospy.logwarn('Service did not process request: %s' % str(e))
        return
    raise_req.table_centroid = table_res.table_centroid
    rospy.loginfo('Raising spine')
    raise_res = self.raise_and_look_push_proxy(raise_req)
    rospy.loginfo('Pushing shit')
    for i in range(num_l_gripper_pushes):
        self.gripper_push_object(self.gripper_push_dist, 'l')
    for i in range(num_r_gripper_pushes):
        self.gripper_push_object(self.gripper_push_dist, 'r')
    for i in range(num_l_sweeps):
        self.sweep_object(self.gripper_sweep_dist, 'l')
    for i in range(num_r_sweeps):
        self.sweep_object(self.gripper_sweep_dist, 'r')
    for i in range(num_l_overhead_pushes):
        self.overhead_push_object(self.overhead_push_dist, 'l')
    for i in range(num_r_overhead_pushes):
        self.overhead_push_object(self.overhead_push_dist, 'r')

def commit(self) -> None:
    self._flush_rpsl_object_upsert_cache()
    self.status_tracker.finalise_transaction()
    try:
        self._transaction.commit()
        self._start_transaction()
    except Exception as e:
        self._transaction.rollback()
        print(f'Error during commit: {e}')
        raise

def _create_tables(self):
    s = LRState(self, 0, AUGSYMBOL, [LRItem(self.grammar.productions[0], 0)])
    state_queue = [s]
    state_id = 1
    while state_queue:
        state = state_queue.pop(0)
        state.closure()
        self._states.append(state)
        goto = OrderedDict()
        self._goto.append(goto)
        actions = OrderedDict()
        if state.state_id == 1:
            actions[EOF] = Action(ACCEPT)
        self._actions.append(actions)
        per_next_symbol = OrderedDict()
        max_prior_per_symbol = {}
        for i in state.items:
            symbol = i.production.rhs[i.position]
            if symbol:
                per_next_symbol.setdefault(symbol, []).append(i)
                prod_prior = i.production.prior
                if symbol in max_prior_per_symbol:
                    old_prior = max_prior_per_symbol[symbol]
                    max_prior_per_symbol[symbol] = max(prod_prior, old_prior)
                else:
                    max_prior_per_symbol[symbol] = prod_prior
            else:
                for t in self._follow_sets[i.production.symbol]:
                    if t is EOF and i.production.prod_id == 0:
                        actions[t] = Action(ACCEPT)
                    elif t in actions:
                        if actions[t].prod is not i.production:
                            print(state.state_id, t)
                            print(actions[t].prod)
                            print(i.production)
                            assert False
                    else:
                        actions[t] = Action(REDUCE, prod=i.production)
        for (symbol, items) in per_next_symbol.items():
            inc_items = [i.get_pos_inc() for i in items]
            maybe_new_state = LRState(self, state_id, symbol, inc_items)
            target_state = maybe_new_state
            try:
                idx = self._states.index(maybe_new_state)
                target_state = self._states[idx]
            except ValueError:
                try:
                    idx = state_queue.index(maybe_new_state)
                    target_state = state_queue[idx]
                except ValueError:
                    pass
            if target_state is maybe_new_state:
                state_queue.append(target_state)
                state_id += 1
            if isinstance(symbol, NonTerminal):
                goto[symbol] = target_state
            elif symbol in actions:
                prod = actions[symbol].prod
                prior = max_prior_per_symbol[symbol]
                if prod.prior == prior:
                    if prod.assoc == ASSOC_NONE:
                        self.print_debug()
                        raise ShiftReduceConflict(state, symbol, prod)
                    elif prod.assoc == ASSOC_RIGHT:
                        actions[symbol] = Action(SHIFT, state=target_state)
                elif prod.prior < prior:
                    actions[symbol] = Action(SHIFT, state=target_state)
            else:
                actions[symbol] = Action(SHIFT, state=target_state)
    if self.debug:
        self.print_debug()

