def position(self):
    timestamp = int(self._setstate.nowPlayingInfo.timestamp)
    if timestamp == 0:
        return 0
    now_utc = datetime.datetime.utcnow()
    timeshift = datetime.datetime(2001, 1, 1, 0, 0) +
        datetime.timedelta(seconds=timestamp)
    diff = (now_utc - timeshift).total_seconds()
    base = self._setstate.nowPlayingInfo.elapsedTime
    return int(base + diff)

def position(self):
    timestamp = int(self._setstate.nowPlayingInfo.timestamp)
    if timestamp == 0:
        return 0
    now_utc = datetime.datetime.utcnow()
    timeshift = datetime.datetime(2001, 1, 1, 0, 0) + datetime.timedelta(seconds=timestamp)
    diff = (now_utc - timeshift).total_seconds()
    base = self._setstate.nowPlayingInfo.elapsedTime
    extra = diff if int(self._setstate.nowPlayingInfo.playbackRate) == 0 else 0
    return int(base + extra)

def rtype_lt((r_tup1, r_tup2), hop):
    v_tuple1, v_tuple2 = hop.inputargs(r_tup1, r_tup1)
    ll_lt = r_tup1.get_ll_lt_function()
    return hop.gendirectcall(ll_lt, v_tuple1, v_tuple2)

def rtype_lt((r_tup1, r_tup2), hop):
    v_tuple1 = hop.inputargs(r_tup1)
    v_tuple2 = hop.inputargs(r_tup2)
    ll_lt = r_tup1.get_ll_lt_function()
    return hop.gendirectcall(ll_lt, v_tuple1, v_tuple2)

