def mark_nodes_failed_after_missing_script_timeout():
    now = datetime.now()
    heartbeat_expired = now - timedelta(minutes=2 * 5)
    qs = Node.objects.filter(status__in=[NODE_STATUS.COMMISSIONING, NODE_STATUS.TESTING], status_expires=None)
    qs = qs.prefetch_related(Prefetch('current_commissioning_script_set', ScriptSet.objects.prefetch_related(Prefetch('scriptresult_set', ScriptResult.objects.defer('output', 'stdout', 'stderr', 'result').prefetch_related(Prefetch('script', Script.objects.only('name', 'may_reboot', 'timeout')))))), Prefetch('current_testing_script_set', ScriptSet.objects.prefetch_related(Prefetch('scriptresult_set', ScriptResult.objects.defer('output', 'stdout', 'stderr', 'result').prefetch_related(Prefetch('script', Script.objects.only('name', 'may_reboot', 'timeout')))))))
    for node in qs:
        if node.status == NODE_STATUS.COMMISSIONING:
            script_set = node.current_commissioning_script_set
        elif node.status == NODE_STATUS.TESTING:
            script_set = node.current_testing_script_set
        script_results = [script_result for script_result in script_set if script_result.status == SCRIPT_STATUS.RUNNING]
        maybe_rebooting = False
        for script_result in script_results:
            if script_result.script and script_result.script.may_reboot:
                maybe_rebooting = True
                break
        flatlined = script_set.last_ping is not None and script_set.last_ping < heartbeat_expired
        if maybe_rebooting and flatlined:
            node.status_expires = now - (now - script_set.last_ping) + timedelta(minutes=NODE_FAILURE_MONITORED_STATUS_TIMEOUTS[node.status])
            node.save(update_fields=['status_expires'])
            continue
        elif flatlined:
            maaslog.info('%s: Has not been heard from for the last 10 minutes' % node.hostname)
            node.mark_failed(comment='Node has not been heard from for the last 10 minutes', script_result_status=SCRIPT_STATUS.TIMEDOUT)
            if not node.enable_ssh:
                maaslog.info('%s: Stopped because SSH is disabled' % node.hostname)
                node.stop(comment='Node stopped because SSH is disabled')
            continue
        for script_result in script_results:
            timeout = None
            for param in script_result.parameters.values():
                if param.get('type') == 'runtime':
                    timeout = param.get('value')
                    break
            if timeout is None and script_result.name in NODE_INFO_SCRIPTS and ('timeout' in NODE_INFO_SCRIPTS[script_result.name]):
                timeout = NODE_INFO_SCRIPTS[script_result.name]['timeout']
            elif timeout is None and script_result.script is not None and (script_result.script.timeout.seconds > 0):
                timeout = script_result.script.timeout
            else:
                continue
            script_expires = script_result.started + timeout + timedelta(minutes=5)
            if script_expires < now:
                script_result.status = SCRIPT_STATUS.TIMEDOUT
                script_result.save(update_fields=['status'])
                maaslog.info("%s: %s has run past it's timeout(%s)" % (node.hostname, script_result.name, str(timeout)))
                node.mark_failed(comment="%s has run past it's timeout(%s)" % (script_result.name, str(timeout)), script_result_status=SCRIPT_STATUS.ABORTED)
                if not node.enable_ssh:
                    maaslog.info('%s: Stopped because SSH is disabled' % node.hostname)
                    node.stop(comment='Node stopped because SSH is disabled')
                break

