        flatlined = script_set.last_ping is not None and script_set.last_ping < heartbeat_expired
        if maybe_rebooting and flatlined:
            node.status_expires = now - (now - script_set.last_ping) + timedelta(minutes=NODE_FAILURE_MONITORED_STATUS_TIMEOUTS[node.status])
            node.save(update_fields=['status_expires'])
            continue
        elif flatlined:
            maaslog.info('%s: Has not been heard from for the last 10 minutes' % node.hostname)
            node.mark_failed(comment='Node has not been heard from for the last 10 minutes', script_result_status=SCRIPT_STATUS.TIMEDOUT)
            if not node.enable_ssh:
                maaslog.info('%s: Stopped because SSH is disabled' % node.hostname)
                node.stop(comment='Node stopped because SSH is disabled')
            continue
        for script_result in script_results:
            timeout = None
            for param in script_result.parameters.values():
                if param.get('type') == 'runtime':
                    timeout = param.get('value')
                    break
            if timeout is None and script_result.name in NODE_INFO_SCRIPTS and ('timeout' in NODE_INFO_SCRIPTS[script_result.name]):
                timeout = NODE_INFO_SCRIPTS[script_result.name]['timeout']
            elif timeout is None and script_result.script is not None and (script_result.script.timeout.seconds > 0):
                timeout = script_result.script.timeout
            else:
                continue
            script_expires = script_result.started + timeout + timedelta(minutes=5)
            if script_expires < now:
                script_result.status = SCRIPT_STATUS.TIMEDOUT
                script_result.save(update_fields=['status'])
                maaslog.info("%s: %s has run past it's timeout(%s)" % (node.hostname, script_result.name, str(timeout)))
                node.mark_failed(comment="%s has run past it's timeout(%s)" % (script_result.name, str(timeout)), script_result_status=SCRIPT_STATUS.ABORTED)
                if not node.enable_ssh:
                    maaslog.info('%s: Stopped because SSH is disabled' % node.hostname)
                    node.stop(comment='Node stopped because SSH is disabled')
                break

def on_button_press(self, target, event, user_data):
    if event.button == 3:
        menu = mk_notebook_context_menu(self)
        menu.connect('hide', MenuHideCallback(self.guake.window).on_hide)
        try:
            menu.popup_at_pointer(event)
        except AttributeError:
            menu.popup(None, None, None, None, event.button, event.time)
    elif event.type == Gdk.EventType.DOUBLE_BUTTON_PRESS and event.button == 1:
        self.new_page_with_focus()
    return False

def __init__(self, label: str, field_names: Union[Sequence[str], str]):
    self.label = label
    if isinstance(field_names, str):
        assert field_names == '*', f'{field_names!r} != "*"'
        self.field_names = field_names
    else:
        self.field_names = [*field_names]

def emitAddressCoordIncrement(self, kernel, ss, tmpVgpr, tmpS01, edge):
    kStr = ''
    kw = self.kernelWriter
    (d1, d0, vc1, vc0) = self.element
    self.coord0Vgpr = None
    kStr += self.kernelWriter.comment1('(d1,vc1,d0,vc0)=(%u,%u,%u,%u)' % (d1, vc1, d0, vc0))
    if ss.optSingleColVgpr:
        self.coord0Vgpr = kw.coord0
    elif not ss.optSharedColVgpr or d1 == vc1 == 0:
        if self.coordOffset0 == 0:
            self.coord0Vgpr = kw.coord0
        elif self.coordOffset0 <= 64:
            self.coord0Vgpr = tmpVgpr
            kStr += inst('_v_add_co_u32', vgpr(self.coord0Vgpr), 'vcc', vgpr(kw.coord0), self.coordOffset0, 'coord0.1: coord0 += d0*sg0*VW + vc0')
        else:
            self.coord0Vgpr = tmpVgpr
            kStr += inst('s_mov_b32', sgpr(tmpS01), self.coordOffset0, 'coordOffset0 d0=%u vc0=%u' % (d0, vc0))
            kStr += inst('_v_add_co_u32', vgpr(self.coord0Vgpr), 'vcc', vgpr(kw.coord0), sgpr(tmpS01), 'coord0.2: coord0 += d0*sg0*VW + vc0')
        if self.newCoord1:
            if not kernel['BufferStore']:
                if self.rowInc == 0:
                    None
                elif self.rowInc <= 64:
                    kStr += inst('_v_add_co_u32', vgpr(self.coord1Vgpr), 'vcc', vgpr(self.kernelWriter.coord1), self.rowInc, 'coord1.1: coord1Vgpr += d1*sg1*VW + vc1')
                else:
                    kStr += inst('s_mov_b32', sgpr(tmpS01), self.rowInc, 'rowInc d1=%u vc1=%u' % (d0, vc0))
                    kStr += inst('_v_add_co_u32', vgpr(self.coord1Vgpr), 'vcc', vgpr(self.kernelWriter.coord1), sgpr(tmpS01), 'coord1.2: coord1 += d1*sg1*VW + vc1')
    return kStr

def i_expect_the_result_is_operator_than_number(_step_obj, operator, number):
    values = _step_obj.context.stash.get('values', [0])
    if not isinstance(values, list):
        values = [values]
    for value in values:
        value = int(value)
        if operator in ('more', 'greater', 'bigger'):
            assert value > number, '{} is not more than {}'.format(value, number)
        elif operator in ('more and equal', 'greater and equal', 'bigger and equal'):
            assert value >= number, '{} is not more and equal than {}'.format(value, number)
        elif operator in ('less', 'lesser', 'smaller'):
            assert value < number, '{} is not less than {}'.format(value, number)
        elif operator in ('less and equal', 'lesser and equal', 'smaller and equal'):
            assert value <= number, '{} is not less and equal than {}'.format(value, number)
        else:
            raise TerraformComplianceNotImplemented('Invalid operator: {}'.format(operator))

