def on_load_pressed(self):
    models = self.data['model']
    representations_model = models['representations']
    representation_item = representations_model.currentItem()
    preset = self.data['label']['preset']
    preset = preset.currentText()
    if representation_item is None:
        return
    for document in representation_item.data(RepresentationsRole):
        try:
            _id = document['_id']
            self.echo('api.registered_host().load(representation="%s")' % _id)
            host = api.registered_host()
            for loader in api.discover(api.Loader):
                if is_compatible_loader(loader, get_representation_context(_id)):
                    host.load(loader, representation=_id, preset=preset)
        except ValueError as e:
            self.echo(e)
            raise
        except NameError as e:
            self.echo(e)
            raise
        except Exception as e:
            self.echo('Program error: %s' % str(e))
            raise
        if self.data['button']['autoclose'].checkState():
            self.close()

def ReadPreprocessingInformation(self, knowledge_base):
    for stream_number in range(1, self._last_preprocess):
        stream_name = u'preprocess.{0:06d}'.format(stream_number)
        if not self._HasStream(stream_name):
            raise IOError(u'No such stream: {0:s}'.format(stream_name))
        data_stream = _SerializedDataStream(self._zipfile, self._zipfile_path, stream_name)
        system_configuration = self._ReadAttributeContainerFromStreamEntry(data_stream, u'preprocess')
        knowledge_base.ReadSystemConfigurationArtifact(stream_number, system_configuration)

