def _got_chunk(self, chunk, timestamp):
    if self._extract_sample(SBE54tpsStatusDataParticle, STATUS_DATA_REGEX_MATCHER, chunk, timestamp):
        return
    if self._extract_sample(SBE54tpsConfigurationDataParticle, CONFIGURATION_DATA_REGEX_MATCHER, chunk, timestamp):
        return
    if self._extract_sample(SBE54tpsEventCounterDataParticle, EVENT_COUNTER_DATA_REGEX_MATCHER, chunk, timestamp):
        return
    if self._extract_sample(SBE54tpsHardwareDataParticle, HARDWARE_DATA_REGEX_MATCHER, chunk, timestamp):
        return
    if self._extract_sample(SBE54tpsSampleRefOscDataParticle, SAMPLE_REF_OSC_MATCHER, chunk, timestamp):
        return
    if self._extract_sample(SBE54tpsSampleDataParticle, SAMPLE_DATA_REGEX_MATCHER, chunk, timestamp):
        pass
    if self._extract_sample(SBE54tpsSampleDataParticle, SAMPLE_DATA_REGEX_MATCHER, chunk, timestamp):
        self._driver_event(DriverAsyncEvent.CONFIG_CHANGE)

def request_send(self, cursor, user, ids, context=None):
    request_history_obj = self.pool.get('res.request.history')
    for request_id in ids:
        request_history_obj.write(cursor, user, [request_id], {'state': 'waiting', 'date_sent': time.strftime('%Y-%m-%d %H:%M:%S')})
        values = request_history_obj.browse(cursor, user, request_id, context=context)
        if len(values.body) > 128:
            values.name = values.body[:125] + '...'
        else:
            values.name = values.body or '/'
        values.req_id = request_id
        request_history_obj.create(cursor, user, values)
    return True

def _session(request):
    engine = request.registry['sqlalchemy.engine']
    session = Session(bind=engine)
    try:
        tm = request.tm
    except AttributeError:
        pass
    else:
        zope.sqlalchemy.register(session, transaction_manager=tm)

    @request.add_finished_callback
    def close_the_sqlalchemy_session(request):
        if session.dirty:
            request.sentry.captureMessage('closing a dirty session', stack=True, extra={'dirty': session.dirty})
        session.close()
    return session

def run_smd0_task(run):
    global_procs = pygion.Tunable.select(pygion.Tunable.GLOBAL_PYS).get()
    for (i, smd_chunk) in enumerate(smd_chunks(run)):
        run_smd_task(smd_chunk, run, point=i)
    pygion.execution_fence(block=True)

def get_extension_name(ext):
    if ext.oid == ExtensionOID.PRECERT_SIGNED_CERTIFICATE_TIMESTAMPS:
        return 'SignedCertificateTimestampList'
    elif ext.oid == ExtensionOID.PRECERT_POISON:
        return 'PrecertPoison'
    return re.sub('^([a-z])', lambda x: x.groups()[0].upper(), ext.oid._name)

