def _attach_pci_devices(self, guest, pci_devs):
    dom = guest._domain
    try:
        for dev in pci_devs:
            guest.attach_device(self._get_guest_pci_device(dev).to_xml())
    except libvirt.libvirtError:
        LOG.error(_LE('Attaching PCI devices %(dev)s to %(dom)s failed.'), {'dev': pci_devs, 'dom': dom.ID()})
        raise

def _startupConfigBrowserSlot(self):
    path = QtGui.QFileDialog.getOpenFileName(self, 'Select a startup configuration', '.', 'Configuration Files (*.cfg);;All Files (*)')
    if not path:
        return
    if not os.access(path, os.R_OK):
        QtGui.QMessageBox.critical(self, 'Startup configuration', 'Cannot read {}'.format(path))
        return
    self.uiStartupConfigLineEdit.clear()
    self.uiStartupConfigLineEdit.setText(path)

def get_fwhm(instrument):
    if instrument == 'naco27':
        if 'fwhm' in VLT_NACO:
            fwhm = VLT_NACO['fwhm']
        else:
            tel_diam = VLT_NACO['diam']
            fwhm = VLT_NACO['lambdal']/tel_diam*206265/VLT_NACO['plsc']
    elif instrument == 'lmircam':
        if 'fwhm' in LBT:
            fwhm = LBT['fwhm']
        else:
            fwhm = LBT['lambdal']/LBT['diam']*206265/LBT['plsc']
    elif not instrument:
        msg = 'One of parameters 'fwhm' or 'instrument' must be given'
        raise RuntimeError(msg)
    else:
        raise RuntimeError('Instrument not recognized')
    return fwhm

