def _find_domain(self, vm):
    found = None
    for domain in self.conn().listAllDomains():
        name = domain.name()
        if not (vm.match_uid_name(name) or vm.fqdn == name or vm.fqdn.startswith(name + '.')):
            continue
        if found is not None:
            raise HypervisorError('Same VM is defined multiple times as "{}" and "{}".'.format(found.name(), name))
        found = domain
    return found

